BEGIN READ ONLY; SELECT json_build_object('at',clock_timestamp(),'rows',count(*),'first_date',min(stockholm_date),'last_date',max(stockholm_date),'series_stored_bytes',sum(pg_column_size(series)),'inputs_stored_bytes',sum(pg_column_size(input_payload)),'logical_row_bytes',sum(pg_column_size(s)),'relation_bytes',pg_total_relation_size('public.venue_sun_geometry_series'),'database_bytes',pg_database_size(current_database()),'sample_sizes',(SELECT json_agg(x) FROM (SELECT venue_id,stockholm_date,pg_column_size(series) AS series_bytes,pg_column_size(input_payload) AS input_bytes FROM public.venue_sun_geometry_series WHERE venue_id IN ('34','8','47') ORDER BY stockholm_date DESC,venue_id LIMIT 3)x)) FROM public.venue_sun_geometry_series s; COMMIT;
